window.__finlexDocLoaded(10053,{"id":10053,"articles":[{"id":1000140,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Establishes standards and provides guidance on engagements to examine and report on prospective financial information (forecasts and projections).","seq":0},{"id":1000141,"no":"ISAE 3400.8–27","heading":"Examination of Prospective Financial Information","text":"Obtain sufficient appropriate evidence whether management's best-estimate assumptions are not unreasonable (forecasts) or hypothetical assumptions are consistent with purpose (projections), and express negative assurance on assumptions plus positive assurance on proper preparation.","seq":1},{"id":1000142,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 2 (ISA 800–810, ISRE, ISAE, ISRS & Assurance Framework)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
